def decode_string(s: str) -> str:
    result_stack = []
    number_stack = []
    current = []
    number = 0

    for ch in s:
        if ch.isdigit():
            number = number * 10 + int(ch)
        elif ch == '[':
            number_stack.append(number)
            result_stack.append(''.join(current))
            current = []
            number = 0
        elif ch == ']':
            k = number_stack.pop()
            previous = result_stack.pop()
            current.append(previous + ''.join(current) * k)
        else:
            current.append(ch)

    return ''.join(current)
```

