def simplify_path(path: str) -> str:
    """Canonicalise an absolute Unix path.

    Handles '.', '..', and repeated slashes. '...' is treated as a normal
    directory/file name. The result has no trailing slash except for root.
    """
    stack: list[str] = []

    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return "/" + "/".join(stack) if stack else "/"
